package org.firstinspires.ftc.teamcode.tuning;

import com.qualcomm.robotcore.eventloop.opmode.LinearOpMode;
import com.qualcomm.robotcore.eventloop.opmode.TeleOp;
import com.qualcomm.robotcore.hardware.Servo;
import com.qualcomm.robotcore.util.Range;

import org.firstinspires.ftc.teamcode.config.DeviceNames;
import org.firstinspires.ftc.teamcode.config.Tuned;

import java.util.Locale;

// Generated by refract-suite ftc-construct. PRACTICE ONLY. Setup program 4 (prerequisites E-7, E-8).
// One servo position per step: hoods (lowest / highest), ramp (stowed / deployed), gates (closed / open),
// then the gate and ramp travel times from slow-motion videos. A servo only moves after square is pressed.
@TeleOp(name = "4 Servo Positions", group = "19859 Setup")
public class ServoPositioner extends LinearOpMode {
    private static final double BIG = 0.01, SMALL = 0.001;
    private static final double FPS = 240;

    private static final class Target {
        final String servo, title, key;
        final String[] instructions;

        Target(String servo, String title, String key, String... instructions) {
            this.servo = servo;
            this.title = title;
            this.key = key;
            this.instructions = instructions;
        }

        // read when used, not when the class loads: a value from the robot's results file arrives after that
        double configValue() {
            try {
                return Tuned.class.getField(key).getDouble(null);
            } catch (ReflectiveOperationException e) {
                return Double.NaN;
            }
        }
    }

    private static final String HOOD_END = "Stop just BEFORE it buzzes, strains or binds (a buzzing servo overheats).";
    private static final Target[] TARGETS = {
            new Target(DeviceNames.FRONT_HOOD, "Front hood: lowest", "frontHoodMin",
                    "Move the front hood to its lowest angle.", HOOD_END),
            new Target(DeviceNames.FRONT_HOOD, "Front hood: highest", "frontHoodMax",
                    "Move the front hood to its highest angle.", HOOD_END),
            new Target(DeviceNames.BACK_HOOD, "Back hood: lowest", "backHoodMin",
                    "Move the back hood to its lowest angle.", HOOD_END),
            new Target(DeviceNames.BACK_HOOD, "Back hood: highest", "backHoodMax",
                    "Move the back hood to its highest angle.", HOOD_END),
            new Target(DeviceNames.RAMP, "Ramp: stowed", "rampStowed",
                    "Move the ramp fully in (folded, inside the 18 in starting size)."),
            new Target(DeviceNames.RAMP, "Ramp: deployed", "rampDeployed",
                    "Move the ramp out to where it picks POLLEN from the bottom of a FLOWER.",
                    "It must stay inside 18 x 24 in when out."),
            new Target(DeviceNames.FRONT_GATE, "Front gate: closed", "frontGateClosed",
                    "Move the front gate so it holds an element away from the front flywheel.",
                    "Check with an element in place: it must not touch the flywheel."),
            new Target(DeviceNames.FRONT_GATE, "Front gate: open", "frontGateOpen",
                    "Move the front gate so an element passes through freely."),
            new Target(DeviceNames.BACK_GATE, "Back gate: closed", "backGateClosed",
                    "Move the back gate so it holds an element away from the back flywheel.",
                    "Check with an element in place: it must not touch the flywheel."),
            new Target(DeviceNames.BACK_GATE, "Back gate: open", "backGateOpen",
                    "Move the back gate so an element passes through freely."),
    };
    private static final int RAMP_STOWED = 4, RAMP_DEPLOYED = 5;
    private static final int FRONT_GATE_CLOSED = 6, FRONT_GATE_OPEN = 7, BACK_GATE_CLOSED = 8, BACK_GATE_OPEN = 9;
    private static final int GATE_TIME = TARGETS.length, RAMP_TIME = TARGETS.length + 1, STEPS = TARGETS.length + 2;

    @Override
    public void runOpMode() {
        Guide g = new Guide(telemetry, 4);
        Servo[] servos = new Servo[TARGETS.length];
        StringBuilder missing = new StringBuilder();
        for (int i = 0; i < TARGETS.length; i++) {
            try {
                servos[i] = hardwareMap.get(Servo.class, TARGETS[i].servo);
            } catch (IllegalArgumentException e) {
                if (missing.indexOf(TARGETS[i].servo) < 0) missing.append(TARGETS[i].servo).append(' ');
            }
        }

        while (opModeInInit()) {
            g.header(0, 0, "Before you start");
            if (missing.length() > 0) g.notReady("servo names " + missing + "(program 1)");
            g.say("You set " + TARGETS.length + " servo positions, then time the gates and the ramp.");
            g.say("Nothing moves until you press square on a step. Keep fingers out of the hoods, ramp and gates.");
            g.doThis("Press START.");
            g.update();
        }
        if (isStopRequested() || missing.length() > 0) return;

        double[] value = new double[TARGETS.length];
        boolean[] live = new boolean[TARGETS.length];
        for (int i = 0; i < TARGETS.length; i++) value[i] = Double.isNaN(TARGETS[i].configValue()) ? 0.5 : TARGETS[i].configValue();
        int step = 0;
        int frames = 0, rampFrames = 0;
        boolean gatesOpen = false, rampOut = false, recorded = false, gateStepStarted = false, rampStepStarted = false;
        String note = "";

        while (opModeIsActive()) {
            boolean next = gamepad1.crossWasPressed(), back = gamepad1.triangleWasPressed(), square = gamepad1.squareWasPressed();
            boolean bigUp = gamepad1.rightBumperWasPressed(), bigDown = gamepad1.leftBumperWasPressed();
            boolean smallUp = gamepad1.rightTriggerWasPressed(), smallDown = gamepad1.leftTriggerWasPressed();
            boolean frameUp = gamepad1.dpadUpWasPressed(), frameDown = gamepad1.dpadDownWasPressed();
            if (next || back) note = "";
            if (back && step > 0 && step <= RAMP_TIME) {
                step--;
                gateStepStarted = false;
                rampStepStarted = false;
            }

            if (step < TARGETS.length) {
                Target target = TARGETS[step];
                if (square) live[step] = true;
                value[step] = Range.clip(value[step] + (bigUp ? BIG : 0) - (bigDown ? BIG : 0)
                        + (smallUp ? SMALL : 0) - (smallDown ? SMALL : 0), 0, 1);
                if (live[step]) servos[step].setPosition(value[step]);

                g.header(step + 1, STEPS, target.title);
                g.why(target.servo.equals(DeviceNames.RAMP) ? "The ramp has two places: folded in, and out at the FLOWER." : target.key.contains("Gate") ? "The gate holds elements off the flywheel until firing." : "The code never moves the hood past these ends.");
                g.goal(target.key.contains("Hood") ? "As far as it goes without buzzing." : target.key.contains("Closed") ? "Holds an element clear of the flywheel." : target.key.contains("Open") ? "An element passes freely." : "Exactly where it should sit.");
                for (String line : target.instructions) g.doThis(line);
                g.value("Position", String.format(Locale.US, "%.3f", value[step]) + (live[step] ? "" : "   (not moving yet: press square)"));
                g.keys("square = move the servo there, R1 / L1 = +/- 0.01, R2 / L2 = +/- 0.001, cross = save and next"
                        + (step > 0 ? ", triangle = back" : ""));
                if (next) {
                    if (!live[step]) {
                        note = "press square first and look at the real position";
                    } else {
                        note = g.record(target.key, String.format(Locale.US, "%.3f", value[step]));
                        // the next step on the same servo starts where this one ended
                        if (step + 1 < TARGETS.length && TARGETS[step + 1].servo.equals(target.servo)
                                && Double.isNaN(TARGETS[step + 1].configValue()) && !live[step + 1]) {
                            value[step + 1] = value[step];
                            live[step + 1] = true;
                        }
                        step++;
                    }
                }
            } else if (step == GATE_TIME) {
                if (!gateStepStarted) {
                    // steps 8 and 10 left both gates open: start this step closed
                    gatesOpen = false;
                    servos[FRONT_GATE_CLOSED].setPosition(value[FRONT_GATE_CLOSED]);
                    servos[BACK_GATE_CLOSED].setPosition(value[BACK_GATE_CLOSED]);
                    gateStepStarted = true;
                }
                if (square) {
                    gatesOpen = !gatesOpen;
                    servos[FRONT_GATE_CLOSED].setPosition(gatesOpen ? value[FRONT_GATE_OPEN] : value[FRONT_GATE_CLOSED]);
                    servos[BACK_GATE_CLOSED].setPosition(gatesOpen ? value[BACK_GATE_OPEN] : value[BACK_GATE_CLOSED]);
                }
                frames = Math.max(0, frames + (frameUp ? 1 : 0) - (frameDown ? 1 : 0) + (bigUp ? 10 : 0) - (bigDown ? 10 : 0));
                g.header(GATE_TIME + 1, STEPS, "Gate travel time");
                g.why("Firing waits this long after opening the gates before feeding.");
                g.goal("A frame count from the slow-motion video (typically a few dozen frames).");
                g.doThis("Film both gates in 240 fps slow motion (phone slo-mo) while pressing square:");
                g.say("each press moves both gates: closed -> open, next press open -> closed.");
                g.doThis("In the video, count the frames from the slower gate starting to move until it is fully open.");
                g.doThis("Enter that count here.");
                g.value("Gates", gatesOpen ? "OPEN" : "closed");
                g.value("Frames", frames + String.format(Locale.US, "  (= %.3f s at 240 fps)", frames / FPS));
                g.keys("square = open / close, dpad up / down = +/- 1 frame, R1 / L1 = +/- 10, cross = save, triangle = back");
                if (next) {
                    if (frames == 0) {
                        note = "enter the frame count first";
                    } else {
                        note = g.record("gateTravelS", String.format(Locale.US, "%.4f", frames / FPS));
                        step++;
                    }
                }
            } else if (step == RAMP_TIME) {
                if (!rampStepStarted) {
                    // the gates go back closed; the ramp starts folded in
                    servos[FRONT_GATE_CLOSED].setPosition(value[FRONT_GATE_CLOSED]);
                    servos[BACK_GATE_CLOSED].setPosition(value[BACK_GATE_CLOSED]);
                    rampOut = false;
                    servos[RAMP_STOWED].setPosition(value[RAMP_STOWED]);
                    rampStepStarted = true;
                }
                if (square) {
                    rampOut = !rampOut;
                    servos[RAMP_STOWED].setPosition(rampOut ? value[RAMP_DEPLOYED] : value[RAMP_STOWED]);
                }
                rampFrames = Math.max(0, rampFrames + (frameUp ? 1 : 0) - (frameDown ? 1 : 0) + (bigUp ? 10 : 0) - (bigDown ? 10 : 0));
                g.header(RAMP_TIME + 1, STEPS, "Ramp travel time");
                g.why("AutoTool shows when the ramp is really out: a RAMP leg only takes POLLEN once it is.");
                g.goal("A frame count from the slow-motion video (typically a hundred or more frames).");
                g.doThis("Film the ramp from the side in 240 fps slow motion (phone slo-mo) while pressing square:");
                g.say("each press moves the ramp: folded in -> out, next press out -> folded in.");
                g.doThis("In the video, count the frames from the ramp starting to move out until it stops at the deployed position.");
                g.doThis("Enter that count here.");
                g.value("Ramp", rampOut ? "OUT" : "folded in");
                g.value("Frames", rampFrames + String.format(Locale.US, "  (= %.3f s at 240 fps)", rampFrames / FPS));
                g.keys("square = out / in, dpad up / down = +/- 1 frame, R1 / L1 = +/- 10, cross = save, triangle = back");
                if (next) {
                    if (rampFrames == 0) {
                        note = "enter the frame count first";
                    } else {
                        note = g.record("rampTravelS", String.format(Locale.US, "%.4f", rampFrames / FPS));
                        step++;
                    }
                }
            } else {
                if (!recorded) {
                    recorded = true;
                    servos[FRONT_GATE_CLOSED].setPosition(value[FRONT_GATE_CLOSED]);
                    servos[BACK_GATE_CLOSED].setPosition(value[BACK_GATE_CLOSED]);
                    servos[RAMP_STOWED].setPosition(value[RAMP_STOWED]);
                    g.loadNextOnStop(this);
                }
                g.header(0, 0, "Done");
                g.finished("");
                for (int i = 0; i < TARGETS.length; i++) g.value(TARGETS[i].key, String.format(Locale.US, "%.3f", value[i]));
                g.value("gateTravelS", String.format(Locale.US, "%.3f", frames / FPS));
                g.value("rampTravelS", String.format(Locale.US, "%.3f", rampFrames / FPS));
            }
            if (!note.isEmpty()) g.warn(note);
            g.update();
        }
    }
}
